/* eslint-disable max-len */

'use strict';

// MODULES //

var isNonNegativeInteger = require( '@stdlib/assert/is-nonnegative-integer' ).isPrimitive;
var isNumber = require( '@stdlib/assert/is-number' ).isPrimitive;
var isBoolean = require( '@stdlib/assert/is-boolean' ).isPrimitive;
var isComplexLike = require( '@stdlib/assert/is-complex-like' );
var isArrayBuffer = require( '@stdlib/assert/is-arraybuffer' );
var isPlainObject = require( '@stdlib/assert/is-plain-object' );
var isDataType = require( '@stdlib/ndarray/base/assert/is-data-type' );
var hasOwnProp = require( '@stdlib/assert/has-own-property' );
var buffer = require( '@stdlib/ndarray/base/buffer' );
var ndarray = require( '@stdlib/ndarray/ctor' );
var defaults = require( '@stdlib/ndarray/defaults' );
var arraybuffer2ndarray = require( '@stdlib/ndarray/from-arraybuffer' );
var complexDataType = require( '@stdlib/complex/dtype' );
var scalar2ndarray = require( '@stdlib/ndarray/from-scalar' );
var format = require( '@stdlib/string/format' );


// VARIABLES //

var DEFAULT_DTYPE = defaults.get( 'dtypes.default' );
var DEFAULT_REAL = defaults.get( 'dtypes.real_floating_point' );
var DEFAULT_CMPLX = defaults.get( 'dtypes.complex_floating_point' );
var DEFAULT_BOOL = defaults.get( 'dtypes.boolean' );
var DEFAULT_ORDER = defaults.get( 'order' );


// FUNCTIONS //

/**
* Resolves the order of the output ndarray.
*
* @private
* @param {*} options - options argument
* @returns {string} order
*/
function resolveOrder( options ) {
	if ( hasOwnProp( options, 'order' ) ) {
		return options.order;
	}
	return DEFAULT_ORDER;
}

/**
* Resolves the default data type for a provided scalar value.
*
* @private
* @param {*} value - scalar value
* @returns {*} data type
*/
function scalar2dtype( value ) { // TODO: replace with `ndarray/base/scalar-dtype` (see https://github.com/stdlib-js/stdlib/issues/11002 and https://github.com/stdlib-js/stdlib/pull/11003)
	var dt;
	if ( isNumber( value ) ) {
		return DEFAULT_REAL;
	}
	if ( isBoolean( value ) ) {
		return DEFAULT_BOOL;
	}
	if ( isComplexLike( value ) ) {
		dt = complexDataType( value );
		if ( dt === null ) {
			return DEFAULT_CMPLX;
		}
		return dt;
	}
	return 'generic';
}

/**
* Returns a zero-dimensional ndarray having a specified data type.
*
* @private
* @param {*} arg - scalar
* @param {*} dtype - data type
* @param {(Options|null)} options - function options
* @param {boolean} [options.readonly=false] - boolean indicating whether to return a read-only ndarray
* @param {string} [options.order='row-major'] - memory layout (either row-major or column-major)
* @returns {(ndarray|null)} zero-dimensional ndarray
*
* @example
* var getDType = require( '@stdlib/ndarray/dtype' );
*
* var v = tensor0dWithDType( 10.0, 'float64', {} );
* // returns <ndarray>
*
* var dt = String( getDType( v ) );
* // returns 'float64'
*/
function tensor0dWithDType( arg, dtype, options ) {
	var opts;
	if ( options === null ) {
		opts = {};
	} else {
		opts = options;
	}
	opts.dtype = dtype;
	return scalar2ndarray( arg, opts );
}


// MAIN //

/**
* Creates a zero-dimensional ndarray.
*
* ## Notes
*
* -   This API is intended to match the conventions of `@stdlib/array/typed`, which has a similar signature.
*
* @param {(ArrayBuffer|*)} [arg] - scalar or buffer
* @param {NonNegativeInteger} [byteOffset=0] - byte offset
* @param {*} [dtype] - data type
* @param {Options} [options] - function options
* @param {boolean} [options.readonly=false] - boolean indicating whether to return a read-only ndarray
* @param {string} [options.order='row-major'] - memory layout (either row-major or column-major)
* @throws {TypeError} first argument must be either a buffer, data type, or options object
* @throws {TypeError} must provide valid options
* @returns {ndarray} zero-dimensional ndarray
*
* @example
* var getDType = require( '@stdlib/ndarray/dtype' );
*
* var arr = tensor0d();
* // returns <ndarray>
*
* var dt = String( getDType( arr ) );
* // returns 'float64'
*
* @example
* var getDType = require( '@stdlib/ndarray/dtype' );
*
* var arr = tensor0d( 1.0 );
* // returns <ndarray>
*
* var dt = String( getDType( arr ) );
* // returns 'float64'
*
* @example
* var getDType = require( '@stdlib/ndarray/dtype' );
*
* var arr = tensor0d( 1.0, 'float32' );
* // returns <ndarray>
*
* var dt = String( getDType( arr ) );
* // returns 'float32'
*
* @example
* var getDType = require( '@stdlib/ndarray/dtype' );
* var ArrayBuffer = require( '@stdlib/array/buffer' );
*
* var buf = new ArrayBuffer( 8 );
* var arr = tensor0d( buf );
* // returns <ndarray>
*
* var dt = String( getDType( arr ) );
* // returns 'float64'
*
* @example
* var getDType = require( '@stdlib/ndarray/dtype' );
* var ArrayBuffer = require( '@stdlib/array/buffer' );
*
* var buf = new ArrayBuffer( 24 );
* var arr = tensor0d( buf, 16 );
* // returns <ndarray>
*
* var dt = String( getDType( arr ) );
* // returns 'float64'
*/
function tensor0d() {
	var nargs;
	var arg0;
	var arg1;
	var arg2;
	var arg3;
	var buf;

	nargs = arguments.length;

	// Case: tensor0d()
	if ( nargs === 0 ) {
		buf = buffer( DEFAULT_DTYPE, 1 );
		return new ndarray( DEFAULT_DTYPE, buf, [], [ 0 ], 0, DEFAULT_ORDER );
	}
	arg0 = arguments[ 0 ];

	// Case: tensor0d( arg0 );
	if ( nargs === 1 ) {
		// Case: tensor0d( dtype )
		if ( isDataType( arg0 ) ) {
			return new ndarray( arg0, buffer( arg0, 1 ), [], [ 0 ], 0, DEFAULT_ORDER );
		}
		// Case: tensor0d( ArrayBuffer )
		if ( isArrayBuffer( arg0 ) ) {
			return arraybuffer2ndarray( DEFAULT_DTYPE, arg0, [], [ 0 ], 0, DEFAULT_ORDER );
		}
		// Case: tensor0d( scalar )
		return tensor0dWithDType( arg0, scalar2dtype( arg0 ), null );
	}
	arg1 = arguments[ 1 ];

	// Case: tensor0d( arg0, arg1 )
	if ( nargs === 2 ) {
		// Case: tensor0d( dtype, options )
		if ( isDataType( arg0 ) ) {
			if ( arg1 === null ) {
				throw new TypeError( format( 'invalid argument. Options argument must be an object. Value: `%s`.', arg1 ) );
			}
			return new ndarray( arg0, buffer( arg0, 1 ), [], [ 0 ], 0, resolveOrder( arg1 ), arg1 );
		}
		// Case: tensor0d( arg0, dtype )
		if ( isDataType( arg1 ) ) {
			// Case: tensor0d( ArrayBuffer, dtype )
			if ( isArrayBuffer( arg0 ) ) {
				return arraybuffer2ndarray( arg1, arg0, [], [ 0 ], 0, DEFAULT_ORDER );
			}
			// Case: tensor0d( scalar, dtype )
			return tensor0dWithDType( arg0, arg1, null );
		}
		// Case: tensor0d( ArrayBuffer, arg1 )
		if ( isArrayBuffer( arg0 ) ) {
			// Case: tensor0d( ArrayBuffer, byteOffset )
			if ( isNonNegativeInteger( arg1 ) ) {
				return arraybuffer2ndarray( DEFAULT_DTYPE, arg0, [], [ 0 ], arg1, DEFAULT_ORDER );
			}
			// Case: tensor0d( ArrayBuffer, options )
			if ( arg1 === null ) {
				throw new TypeError( format( 'invalid argument. Options argument must be an object. Value: `%s`.', arg1 ) );
			}
			return arraybuffer2ndarray( DEFAULT_DTYPE, arg0, [], [ 0 ], 0, resolveOrder( arg1 ), arg1 );
		}
		// Case: tensor0d( scalar, options )
		if ( arg1 === null ) {
			throw new TypeError( format( 'invalid argument. Options argument must be an object. Value: `%s`.', arg1 ) );
		}
		return tensor0dWithDType( arg0, scalar2dtype( arg0 ), arg1 );
	}
	arg2 = arguments[ 2 ];

	// Case: tensor0d( arg0, arg1, arg2 )
	if ( nargs === 3 ) {
		// Case: tensor0d( ArrayBuffer, byteOffset, dtype )
		if ( isDataType( arg2 ) ) {
			if ( !isArrayBuffer( arg0 ) ) {
				throw new TypeError( format( 'invalid argument. First argument must be an ArrayBuffer. Value: `%s`.', arg0 ) );
			}
			if ( !isNonNegativeInteger( arg1 ) ) {
				throw new TypeError( format( 'invalid argument. Byte offset must be a nonnegative integer. Value: `%s`.', arg1 ) );
			}
			return arraybuffer2ndarray( arg2, arg0, [], [ 0 ], arg1, DEFAULT_ORDER );
		}
		// Case: tensor0d( arg0, dtype, options )
		if ( isDataType( arg1 ) ) {
			if ( arg2 === null ) {
				throw new TypeError( format( 'invalid argument. Options argument must be an object. Value: `%s`.', arg2 ) );
			}
			// Case: tensor0d( ArrayBuffer, dtype, options )
			if ( isArrayBuffer( arg0 ) ) {
				return arraybuffer2ndarray( arg1, arg0, [], [ 0 ], 0, resolveOrder( arg2 ), arg2 );
			}
			// Case: tensor0d( scalar, dtype, options )
			return tensor0dWithDType( arg0, arg1, arg2 );
		}
		// Case: tensor0d( ArrayBuffer, byteOffset, options )
		if ( !isArrayBuffer( arg0 ) ) {
			throw new TypeError( format( 'invalid argument. First argument must be an ArrayBuffer. Value: `%s`.', arg0 ) );
		}
		if ( !isNonNegativeInteger( arg1 ) ) {
			throw new TypeError( format( 'invalid argument. Byte offset must be a nonnegative integer. Value: `%s`.', arg1 ) );
		}
		if ( arg2 === null ) {
			throw new TypeError( format( 'invalid argument. Options argument must be an object. Value: `%s`.', arg2 ) );
		}
		return arraybuffer2ndarray( DEFAULT_DTYPE, arg0, [], [ 0 ], arg1, resolveOrder( arg2 ), arg2 );
	}
	arg3 = arguments[ 3 ];

	// Case: tensor0d( ArrayBuffer, byteOffset, dtype, options )
	if ( !isArrayBuffer( arg0 ) ) {
		throw new TypeError( format( 'invalid argument. First argument must be an ArrayBuffer. Value: `%s`.', arg0 ) );
	}
	if ( !isNonNegativeInteger( arg1 ) ) {
		throw new TypeError( format( 'invalid argument. Byte offset must be a nonnegative integer. Value: `%s`.', arg1 ) );
	}
	if ( !isDataType( arg2 ) ) {
		throw new TypeError( format( 'invalid argument. Third argument must be a recognized/supported data type. Value: `%s`.', arg2 ) );
	}
	if ( !isPlainObject( arg3 ) ) {
		throw new TypeError( format( 'invalid argument. Options argument must be an object. Value: `%s`.', arg3 ) );
	}
	return arraybuffer2ndarray( arg2, arg0, [], [ 0 ], arg1, resolveOrder( arg3 ), arg3 );
}


// EXPORTS //

module.exports = tensor0d;
